function n(t){return t=Number(t)||0,t>=1e8?(t/1e8).toFixed(1).replace(/\.0$/,"")+"亿":t>=1e4?(t/1e4).toFixed(1).replace(/\.0$/,"")+"万":String(t)}function o(t){t=Math.max(0,Math.round(Number(t)||0));const r=Math.floor(t/60),a=t%60;return String(r).padStart(2,"0")+":"+String(a).padStart(2,"0")}function i(t){const r=Date.now()-Number(t),a=6e4;if(r<a)return"刚刚";if(r<60*a)return Math.floor(r/a)+"分钟前";if(r<1440*a)return Math.floor(r/(60*a))+"小时前";if(r<720*60*a)return Math.floor(r/(1440*a))+"天前";const e=new Date(t);return`${e.getFullYear()}-${String(e.getMonth()+1).padStart(2,"0")}-${String(e.getDate()).padStart(2,"0")}`}function u(t){const r=new Date(Number(t));return`${r.getFullYear()}-${String(r.getMonth()+1).padStart(2,"0")}-${String(r.getDate()).padStart(2,"0")} ${String(r.getHours()).padStart(2,"0")}:${String(r.getMinutes()).padStart(2,"0")}`}export{u as a,o as b,n as f,i as t};
